<script setup>
import {computed,shallowRef} from 'vue'
import {useRoute} from 'vue-router'
import {products,path,fmt} from '../data'
import {session,openModal} from '../session'
import Coin from '../components/Coin.vue'
import Icon from '../components/Icon.vue'
const route=useRoute(),filter=shallowRef('全部'),sort=shallowRef(false)
const section=computed(()=>route.params.section||'simple'),product=computed(()=>section.value==='simple'&&route.params.id?products.find(p=>p.id===route.params.id):null)
const visible=computed(()=>products.filter(p=>filter.value==='全部'||p.type===filter.value).toSorted((a,b)=>sort.value?a.rate-b.rate:b.rate-a.rate))
const featured=[products[1],products[4],products[7]]
function subscribe(p){openModal('subscribe','申購',{...p,max:500000})}
</script>
<template>
<div v-if="product" class="detail-wrap"><RouterLink :to="path('/earn/simple')" class="muted">{{ $tr("← 返回理財中心") }}</RouterLink><div class="card card-glow summary-line"><div class="coin-label"><Coin :symbol="product.symbol"/><div><h1>{{ $tr(product.name) }}</h1><p class="muted" style="margin-top:10px">{{ $tr(product.symbol) }} · {{ $tr(product.days?product.days+' 天':'活期') }}</p></div></div><div><strong class="metric">{{ $tr(product.rate.toFixed(4)) }}%</strong><small class="muted">{{ $tr(" 預估日利率") }}</small><p class="muted" style="text-align:right;margin-top:8px">{{ $tr("≈ 年化 ") }}{{ $tr((product.rate*365).toFixed(2)) }}%</p></div></div><div class="card"><h2>{{ $tr("資金時間線") }}</h2><div class="timeline"><div><small>{{ $tr("申購") }}</small>{{ $tr("現在") }}</div><div><small>{{ $tr("起息") }}</small>{{ $tr("審核通過後次日") }}</div><div><small>{{ $tr("到期") }}</small>{{ $tr(product.days?'起息後 '+product.days+' 天':'隨時贖回') }}</div></div><small class="muted">{{ $tr("收益發放　") }}</small>{{ $tr("到期/贖回時一次性發放") }}</div><div class="two-cols"><div class="card"><h2>{{ $tr("申購規則") }}</h2><dl class="details-list"><dt>{{ $tr("最低申購") }}</dt><dd>{{ $tr(fmt(product.min)) }} {{ $tr(product.symbol) }}</dd><dt>{{ $tr("最高申購") }}</dt><dd>500,000 {{ $tr(product.symbol) }}</dd><dt>{{ $tr("單用戶限額") }}</dt><dd>100,000 {{ $tr(product.symbol) }}</dd></dl></div><div class="card"><h2>{{ $tr("產品額度") }}</h2><div class="progress"><span style="width:1%"></span></div><small class="muted">{{ $tr("已申購 0%") }}</small><dl class="details-list"><dt>{{ $tr("剩餘額度") }}</dt><dd>{{ $tr(product.remaining) }} {{ $tr(product.symbol) }}</dd><dt>{{ $tr("總申購量") }}</dt><dd>{{ $tr(fmt(product.min)) }} {{ $tr(product.symbol) }}</dd></dl></div></div><div class="card"><h2>{{ $tr("風險揭示") }}</h2><p class="muted" style="line-height:1.8;margin-top:16px">{{ $tr("· 收益不保證；可能隨市場狀況變動。") }}<br/>{{ $tr("· 定期產品提前贖回將放棄已計收益。") }}<br/>{{ $tr("· 本地頁面僅復刻原站展示，不提供真實申購。") }}</p></div><div class="sticky-action"><div><b class="green-link">{{ $tr(product.rate.toFixed(4)) }}%</b><small class="muted">{{ $tr("　日利率 · ") }}{{ $tr(product.days||'活期') }}{{ $tr(" · 起投 ") }}{{ $tr(fmt(product.min)) }} {{ $tr(product.symbol) }}</small></div><button class="primary-button" @click="subscribe(product)">{{ $tr("申購") }}</button></div></div>
<div v-else class="page-wrap finance-page"><nav class="subnav" :aria-label="$tr(&quot;理財模組導覽&quot;)"><RouterLink :to="path('/earn/simple')">{{ $tr("理財產品") }}</RouterLink><RouterLink :to="path('/earn/my-earnings')">{{ $tr("我的理財") }}</RouterLink><RouterLink :to="path('/earn/loan')">{{ $tr("借貸") }}</RouterLink><RouterLink :to="path('/earn/loan/my')">{{ $tr("我的借貸") }}</RouterLink></nav>
<template v-if="section==='simple'"><div class="two-cols page-hero"><div><small class="page-kicker">{{ $tr("被動收益") }}</small><h1 class="page-title">{{ $tr("理財中心") }}</h1><p class="page-desc">{{ $tr("讓閒置資產持續生息。透明參考收益率 —— 為長期持有者打造，而非高頻交易者。") }}</p><div class="filter-row"><span class="tag-chip">{{ $tr("日利率最高 0.0273%") }}</span><span class="tag-chip">{{ $tr("活期 & 定期") }}</span></div></div><div class="card card-glow"><p class="mini-label">{{ $tr("總持倉估值") }}</p><div class="three-cols section-gap"><div v-for="label in ['總持倉估值','本金','應計收益','累計收益','預估每日收益']" :key="label"><p class="mini-label">{{ $tr(label) }}</p><strong style="display:block;margin-top:12px;font:600 18px 'IBM Plex Mono'">$0.00</strong></div></div></div></div><div class="section-row section-gap" style="margin-bottom:20px"><h2>{{ $tr("熱門精選") }}</h2><small class="muted">{{ $tr("3 款產品") }}</small></div><div class="four-cols"><RouterLink v-for="p in featured" :key="p.id" :to="path('/earn/simple/'+p.id)" class="card card-glow"><small class="negative">{{ $tr("熱門") }}</small><div class="coin-label" style="margin:16px 0 24px"><Coin :symbol="p.symbol"/><div>{{ $tr(p.name) }}<small class="muted" style="display:block">{{ $tr(p.days?p.days+' 天':'活期') }}</small></div></div><p class="metric">{{ $tr(p.rate.toFixed(4)) }}<small>%</small></p><p class="mini-label">{{ $tr("預估日利率") }}</p><p class="mini-label" style="margin-top:8px">{{ $tr("≈ 年化 ") }}{{ $tr((p.rate*365).toFixed(2)) }}%</p><p class="green-link" style="margin-top:20px;font-size:0.75rem">{{ $tr("申購 ›") }}</p></RouterLink></div><div class="filter-row"><button v-for="f in ['全部','活期','定期']" :key="f" :class="{active:filter===f}" :aria-pressed="filter===f" @click="filter=f">{{ $tr(f) }}</button><button @click="sort=!sort">{{ $tr("日利率 ") }}{{ $tr(sort?'↑':'↓') }}</button></div><div class="finance-table card"><table><thead><tr><th>{{ $tr("產品") }}</th><th>{{ $tr("類型") }}</th><th>{{ $tr("期限") }}</th><th>{{ $tr("起投") }}</th><th>{{ $tr("剩餘額度") }}</th><th>{{ $tr("日利率") }}</th><th>{{ $tr("操作") }}</th></tr></thead><tbody><tr v-for="p in visible" :key="p.id"><td><RouterLink :to="path('/earn/simple/'+p.id)" class="coin-label"><Coin :symbol="p.symbol"/><span>{{ $tr(p.name) }}<small class="muted" style="display:block">{{ $tr(p.symbol) }}</small></span></RouterLink></td><td data-label="類型">{{ $tr(p.type) }}</td><td data-label="期限">{{ $tr(p.days?p.days+' 天':'活期') }}</td><td data-label="起投">{{ $tr(fmt(p.min)) }} {{ $tr(p.symbol) }}</td><td data-label="剩餘額度">{{ $tr(p.remaining) }} {{ $tr(p.symbol) }}</td><td data-label="日利率" class="green-link">{{ $tr(p.rate.toFixed(4)) }}%</td><td><RouterLink :to="path('/earn/simple/'+p.id)" class="pill primary">{{ $tr("申購") }}</RouterLink></td></tr></tbody></table></div><p class="mini-label section-gap">{{ $tr("申購前請查看各產品的條款與贖回規則。收益為原站展示的預估值，可能變動。") }}</p></template>
<template v-else-if="section==='loan'&&!route.params.id"><small class="page-kicker">{{ $tr("抵押借貸") }}</small><h1 class="page-title">{{ $tr("加密借貸") }}</h1><p class="page-desc">{{ $tr("以加密資產，或房產、銀行存款等線下資產作抵押借款。選擇幣種查看日利率、額度與期限。") }}</p><div class="three-cols section-gap"><div class="card"><div class="coin-label"><Coin symbol="USD"/>{{ $tr("USD") }}</div><p class="mini-label section-gap">{{ $tr("日利率") }}</p><strong class="metric">0.10%</strong><dl class="details-list"><dt>{{ $tr("可借區間") }}</dt><dd>{{ $tr("100 – 100,000 USD") }}</dd><dt>{{ $tr("期限") }}</dt><dd>{{ $tr("7 / 14 / 30 / 60 / 90 / 180 天") }}</dd></dl><button class="primary-button wide-button section-gap" @click="openModal('loan','加密借貸',{name:'USD 抵押借貸',symbol:'USD',min:100,rate:.1,days:30})">{{ $tr("去借款 ") }}<Icon name="arrow-right"/></button></div></div></template>
<template v-else><h1 class="page-title">{{ $tr(section==='loan'?'我的借貸':'我的理財') }}</h1><div class="card empty"><Icon name="wallet"/><p v-if="!session.subscriptions.length">{{ $tr("暫無持倉") }}</p><div v-else v-for="(s,i) in session.subscriptions" :key="i" class="summary-line" style="padding:16px">{{ $tr(s.name) }}<b>{{ $tr(fmt(s.amount)) }}{{ $tr(" USD") }}</b><span class="positive">{{ $tr(s.status) }}</span></div><RouterLink class="green-link section-gap" :to="path('/earn/simple')">{{ $tr("瀏覽理財產品 →") }}</RouterLink></div></template>
</div></template>
<style scoped>.finance-table{padding:0;overflow:hidden}.finance-table .pill{padding:6px 16px;font-size:0.75rem}.finance-table td{font-size:0.8125rem;padding:20px}.finance-table td:first-child{width:30%}.finance-table h2{font-size:1rem}@media(max-width:900px){.finance-table table,.finance-table tbody{display:block}.finance-table thead{display:none}.finance-table tr{display:grid;grid-template-columns:1fr 1fr;padding:20px;gap:12px;border-bottom:1px solid #ffffff0c}.finance-table td{display:block;padding:0;border:0}.finance-table td:first-child{grid-column:1/-1;width:auto;margin-bottom:8px}.finance-table td[data-label]::before{content:attr(data-label);display:block;font-size:0.6875rem;color:#fff6;margin-bottom:5px}.finance-table td:last-child{grid-column:1/-1;text-align:right}}
</style>
